{
  "version": 1,
  "kind": "ArchitectureContract",
  "domains": {
    "core": {
      "owner": "core-team",
      "paths": ["core/**"],
      "public_interfaces": ["core/store.ts"]
    },
    "apps": {
      "owner": "apps-team",
      "paths": ["apps/**"]
    }
  },
  "rules": [
    {
      "id": "CORE-NOT-APPS",
      "kind": "forbidden-dependency",
      "source": ["core/**"],
      "target": ["apps/**"],
      "severity": "block",
      "reason": "Core must not import application code.",
      "remediation": "Invert the dependency through a core-owned interface."
    },
    {
      "id": "NO-CYCLES",
      "kind": "cycles",
      "severity": "review",
      "reason": "Import cycles hide ownership.",
      "remediation": "Extract the shared piece into a third module."
    },
    {
      "id": "SMALL-MODULES",
      "kind": "max-module-lines",
      "source": ["lib/**"],
      "limit": 5,
      "severity": "inform",
      "reason": "Large modules are hard to review.",
      "remediation": "Split the module by responsibility."
    }
  ]
}

